def derivatives(n,F,vs,order=1):
 labels=[];ks=[];es=[]
 for i in vs:
  di=S.diff(F,i)
  if order==1:labels.append('f_{'+S.latex(i)+'}='+S.latex(S.simplify(di)));ks.append('다른 변수를 고정하고 '+M(i)+'로 미분: '+M(di)+'.');es.append('Hold other variables fixed and differentiate in '+M(i)+': '+M(di)+'.')
  else:
   ks.append('1계 '+M(i)+' 미분: '+M(di)+'.');es.append('First derivative in '+M(i)+': '+M(di)+'.')
   for j in vs:labels.append('f_{'+S.latex(i)+S.latex(j)+'}='+S.latex(S.simplify(S.diff(di,j))))
 ans=r'\('+';\quad '.join(labels)+r'\).';add(n,'f='+M(F)+f'의 모든 {order}계 편도함수를 구하라.','For f='+M(F)+f', find all order-{order} partial derivatives.',ks,es,ans,ans,'혼합편미분은 식이 매끄러운 정의역에서 서로 교환됨을 검사했다.','Mixed partials were checked to commute on the smooth domain.')
for row in [(13,(5*y**3+2*x*x*y)**8,[x,y]),(14,(u+2*v)/(u*u+v*v),[u,v]),(15,a*a*S.log(a*a+b*b),[a,b]),(16,S.exp(x*z)*S.sin(y/z),[x,y,z]),(17,u*S.atan(v*S.sqrt(w)),[u,v,w])]:derivatives(*row)
add(18,r'\(C=1449.2+4.6T-0.055T^2+0.00029T^3+(1.34-0.01T)(S-35)+0.016D\). T=10°C,S=35‰,D=100m에서 세 편도함수와 물리적 의미를 구하라.',r'For \(C=1449.2+4.6T-0.055T^2+0.00029T^3+(1.34-0.01T)(S-35)+0.016D\), find the three partials at T=10°C,S=35‰,D=100m and interpret them.',['CT=4.6−0.11T+0.00087T²−0.01(S−35)=3.587.','CS=1.34−0.01T=1.24, CD=0.016. 각 값은 다른 두 조건을 고정한 음속 변화율이다.'],['CT=4.6−0.11T+0.00087T²−0.01(S−35)=3.587.','CS=1.24,CD=0.016, each holding the other two conditions fixed.'],'CT=3.587(m/s)/°C, CS=1.24(m/s)/‰, CD=0.016(m/s)/m.','CT=3.587(m/s)/°C, CS=1.24(m/s)/‰, CD=0.016(m/s)/m.')
for row in [(19,4*x**3-x*y*y,[x,y]),(20,x*S.exp(-2*y),[x,y]),(21,x**k*y**l*z**m,[x,y,z]),(22,r*S.cos(s+2*t),[r,s,t])]:derivatives(*row,order=2)
