def plane(n,F,P,graph=False):
 sub=dict(zip([x,y,z],P));G=S.Matrix([S.diff(F,j).subs(sub) for j in [x,y,z]]);assert F.subs(sub)==0;eq=S.expand(G.dot(S.Matrix([x,y,z])-S.Matrix(P)));line=S.Matrix(P)+t*G
 st=M(F)+'=0, P='+M(S.Tuple(*P))+'. '
 add(n,st+'접평면과 법선을 구하라.'+(' 세 대상을 함께 그려라.' if graph else ''),st+'Find the tangent plane and normal.'+(' Plot all three objects.' if graph else ''),['P의 법선은 기울기 '+M(G)+'.','기울기와 위치차의 내적을0으로 놓으면 접평면, P에서 기울기 방향으로 직선을 그으면 법선이다.'],['The normal at P is the gradient '+M(G)+'.','Zero dot product with displacement gives the tangent plane; the line through P in this gradient direction is normal.'],'접평면 '+M(eq)+'=0; 법선 '+M(line)+', t∈R.','Tangent plane '+M(eq)+'=0; normal '+M(line)+', t∈R.',parts=[] if graph else ['a','b'])
for row in [(25,3*x*x-y*y+2*x-z,[1,-2,1]),(26,S.exp(x)*S.cos(y)-z,[0,0,1]),(27,x*x+2*y*y-3*z*z-3,[2,-1,1]),(28,x*y+y*z+z*x-3,[1,1,1]),(29,S.sin(x*y*z)-x-2*y-3*z,[2,-1,0]),(30,x*x+y**4-z,[1,1,2],True)]:plane(*row)
