add(35,r'u=x²y³+z⁴, x=p+3p²,y=peᵖ,z=p sinp일 때 du/dp를 연쇄법칙으로 구하라.',r'For u=x²y³+z⁴,x=p+3p²,y=peᵖ,z=p sinp, find du/dp by the chain rule.',['ux=2xy³,uy=3x²y²,uz=4z³.','u′=2xy³(1+6p)+3x²y²eᵖ(1+p)+4z³(sinp+p cosp), 주어진 x,y,z를 대입한다.'],['ux=2xy³,uy=3x²y²,uz=4z³.','u′=2xy³(1+6p)+3x²y²eᵖ(1+p)+4z³(sinp+p cosp); substitute the given x,y,z.'],M(der)+'.',M(der)+'.','직접 합성식을 미분한 결과와 기호적으로 일치함을 검사했다.','Symbolically checked against direct differentiation of the composite.')
add(36,'v=x²sin y+yeˣʸ,x=s+2t,y=st에서 s=0,t=1의 vs,vt를 구하라.','For v=x²sin y+yeˣʸ,x=s+2t,y=st, find vs,vt at s=0,t=1.',['입력은 (x,y)=(2,0), vx=0,vy=5.','xs=1,ys=t=1,xt=2,yt=s=0이므로 vs=5,vt=0.'],['The inner point is (2,0), where vx=0,vy=5.','With xs=1,ys=1,xt=2,yt=0, the chain rule gives vs=5,vt=0.'],'vs=5, vt=0.','vs=5, vt=0.')
add(37,'z=f(g(s,t),h(s,t)),g(1,2)=3,h(1,2)=6,gs=−1,gt=4,hs=−5,ht=10,fx(3,6)=7,fy(3,6)=8이다. zs,zt(1,2)를 구하라.','For z=f(g(s,t),h(s,t)),g(1,2)=3,h(1,2)=6,gs=−1,gt=4,hs=−5,ht=10,fx(3,6)=7,fy(3,6)=8. Find zs,zt at(1,2).',['zs=fx gs+fy hs=7(−1)+8(−5).','zt=fx gt+fy ht=7·4+8·10.'],['zs=fx gs+fy hs=7(−1)+8(−5).','zt=fx gt+fy ht=7·4+8·10.'],'zs=−47,zt=108.','zs=−47,zt=108.')
add(38,'w=f(t,u,v)이고 t,u,v는 각각 p,q,r,s의 함수이다. 나무도표와 네 연쇄법칙을 쓰라.','Let w=f(t,u,v), with t,u,v each depending on p,q,r,s. Draw a tree and state the four chain rules.',['w에서 t,u,v로 가지를 내고 각 중간변수에서 p,q,r,s로 가지를 낸다.','각 입력 j에 대해 세 경로의 곱을 더한다.'],['Branch from w to t,u,v and from each intermediate to p,q,r,s.','For each input j, sum the products on its three paths.'],r'\(w_j=w_t t_j+w_u u_j+w_v v_j,\quad j=p,q,r,s\).',r'\(w_j=w_t t_j+w_u u_j+w_v v_j,\quad j=p,q,r,s\).')
add(39,r'z=y+f(x²−y²)에서 \(yz_x+xz_y=x\)임을 보여라.',r'For z=y+f(x²−y²), prove \(yz_x+xz_y=x\).',['q=x²−y²라 하면 zx=2x f′(q),zy=1−2y f′(q).','y,x를 곱해 더하면 f′ 항이 소거되고 x가 남는다.'],['Let q=x²−y². Then zx=2x f′(q),zy=1−2y f′(q).','Multiplication by y,x and addition cancel the f′ terms, leaving x.'],r'\(yz_x+xz_y=x\).',r'\(yz_x+xz_y=x\).')
add(40,'삼각형 두 변 x=40in,y=50in, 끼인각θ=π/6에서 x′=3in/s,y′=−2in/s,θ′=0.05rad/s이다. 넓이 변화율을 구하라.','A triangle has x=40in,y=50in, included angleθ=π/6, with x′=3in/s,y′=−2in/s,θ′=0.05rad/s. Find its area rate.',['A=xy sinθ/2, A′=(x′y+xy′)sinθ/2+xy cosθ θ′/2.','대입하면 (150−80)/4+1000(√3/2)(0.05).'],['A=xy sinθ/2, so A′=(x′y+xy′)sinθ/2+xy cosθ θ′/2.','Substitution gives(150−80)/4+1000(√3/2)(0.05).'],'17.5+25√3 in²/s.','17.5+25√3 in²/s.')
add(41,r'z=f(u,v),u=xy,v=y/x,f∈C²일 때 \(x^2z_{xx}-y^2z_{yy}=-4uvf_{uv}+2vf_v\)를 증명하라.',r'For z=f(u,v),u=xy,v=y/x,f∈C², prove \(x^2z_{xx}-y^2z_{yy}=-4uvf_{uv}+2vf_v\).',[r'\(z_{xx}=y^2f_{uu}-2y^2f_{uv}/x^2+y^2f_{vv}/x^4+2yf_v/x^3\).',r'\(z_{yy}=x^2f_{uu}+2f_{uv}+f_{vv}/x^2\).','각각 x²,y²를 곱해 빼면 fuu,fvv가 소거되며 y²=uv,y/x=v이다.'],[r'\(z_{xx}=y^2f_{uu}-2y^2f_{uv}/x^2+y^2f_{vv}/x^4+2yf_v/x^3\).',r'\(z_{yy}=x^2f_{uu}+2f_{uv}+f_{vv}/x^2\).','Multiply by x²,y² and subtract; fuu,fvv cancel, while y²=uv and y/x=v.'],r'\(x^2z_{xx}-y^2z_{yy}=-4uvf_{uv}+2vf_v\), x≠0.',r'\(x^2z_{xx}-y^2z_{yy}=-4uvf_{uv}+2vf_v\), x≠0.')
add(42,'cos(xyz)=1+x²y²+z²에서 zx,zy를 조사하라.','Investigate zx,zy for cos(xyz)=1+x²y²+z².',['F=cos(xyz)−1−x²y²−z²로 두면 형식적으로 zx=−Fx/Fz,zy=−Fy/Fz를 쓸 수 있다.',r'형식은 \(z_x=-\frac{yz\sin(xyz)+2xy^2}{xy\sin(xyz)+2z},\quad z_y=-\frac{xz\sin(xyz)+2x^2y}{xy\sin(xyz)+2z}\).','그러나 실수에서 좌변≤1, 우변≥1이므로 모든 해는 z=0,xy=0이다. 따라서 Fz=0이고 열린 xy근방에 z(x,y)를 정의하는 곡면이 아니다.'],['Set F=cos(xyz)−1−x²y²−z². Formally one would use zx=−Fx/Fz,zy=−Fy/Fz.',r'The formal expressions are \(z_x=-\frac{yz\sin(xyz)+2xy^2}{xy\sin(xyz)+2z},\quad z_y=-\frac{xz\sin(xyz)+2x^2y}{xy\sin(xyz)+2z}\).','For real solutions the left side≤1 and right side≥1 force z=0,xy=0. Thus Fz=0 everywhere feasible, and no surface z(x,y) exists on an open xy neighborhood.'],'형식적 비는 위와 같지만 실제 실수해에서 모두0/0이다. 이 제약은 통상적인 zx,zy를 정의하지 않는다.','The formal ratios above are0/0 on every real solution. The constraint does not define ordinary zx,zy.','음함수정리의 Fz≠0 가정을 실제로 검사한 결과이다.','This conclusion checks the actual nonzero-Fz hypothesis of the implicit function theorem.')
derivatives(43,x*x*S.exp(y*z*z),[x,y,z]);E[-1]['statement']['ko']='f='+M(x*x*S.exp(y*z*z))+'의 기울기를 구하라.';E[-1]['statement']['en']='Find the gradient of f='+M(x*x*S.exp(y*z*z))+'.';E[-1]['answer']=pair(M(S.Matrix([2*x*S.exp(y*z*z),x*x*z*z*S.exp(y*z*z),2*x*x*y*z*S.exp(y*z*z)])),M(S.Matrix([2*x*S.exp(y*z*z),x*x*z*z*S.exp(y*z*z),2*x*x*y*z*S.exp(y*z*z)])))
add(44,'미분가능 함수의 방향미분은 언제 (a) 최대 (b) 최소 (c)0 (d) 최대값의 절반인가?','When is a differentiable function’s directional derivative (a) maximal, (b) minimal, (c) zero, and (d) half its maximum?',[r'기울기가0이 아니면 \(D_uf=\|\nabla f\|\cos\theta\).','cosθ가 각각1,−1,0,1/2가 되는 각을 찾는다. 기울기가0이면 모든 방향미분이0이므로 모든 단위 방향이 네 조건을 만족한다.'],[r'For nonzero gradient, \(D_uf=\|\nabla f\|\cos\theta\).','Use cosθ=1,−1,0,1/2 respectively. For zero gradient every unit direction satisfies all four zero-valued conditions.'],'비영 기울기와 각: (a)0° (b)180° (c)90° (d)60°.','Angles to a nonzero gradient: (a)0° (b)180° (c)90° (d)60°.',parts=['a','b','c','d'])
for n,F,vs,P,V in [(45,x*x*S.exp(-y),[x,y],[-2,0],[4,-3]),(46,x*x*y+x*S.sqrt(1+z),[x,y,z],[1,2,3],[2,1,-2])]:
 G=S.Matrix([S.diff(F,j).subs(dict(zip(vs,P))) for j in vs]);V=S.Matrix(V);U=V/S.sqrt(V.dot(V));value=S.simplify(G.dot(U))
 add(n,'f='+M(F)+', P='+M(S.Tuple(*P))+', v='+M(V)+'의 방향미분을 구하라.','Find the directional derivative for f='+M(F)+', P='+M(S.Tuple(*P))+', v='+M(V)+'.',['P의 기울기는 '+M(G)+', 단위 방향은 '+M(U)+'.','내적을 취하면 '+M(value)+'.'],['The gradient at P is '+M(G)+', and the unit direction '+M(U)+'.','Their dot product is '+M(value)+'.'],M(value),M(value))
for n,F,vs,P in [(47,x*x*y+S.sqrt(y),[x,y],[2,1]),(48,z*S.exp(x*y),[x,y,z],[0,1,2])]:
 G=S.Matrix([S.diff(F,j).subs(dict(zip(vs,P))) for j in vs]);N=S.sqrt(G.dot(G));U=G/N;ans='rate='+M(N)+', u='+M(U)
 add(n,'f='+M(F)+', P='+M(S.Tuple(*P))+'에서 최대증가율과 방향을 구하라.','Find maximum increase rate and direction for f='+M(F)+' at P='+M(S.Tuple(*P))+'.',['기울기는 '+M(G)+'.','최대율은 그 길이, 방향은 기울기를 길이로 나눈 단위벡터이다.'],['The gradient is '+M(G)+'.','The maximum rate is its norm; normalize the gradient for its direction.'],ans,ans)
add(49,'허리케인 풍속 등고선은5kn 간격이다. Homestead에서 눈 방향의 국소 선간격은 지도 축척상 약10mi이다. 그 방향 풍속 변화율을 추정하라.','Hurricane wind contours differ by5kn. Near Homestead, their spacing toward the eye is about10mi by the map scale. Estimate the directional wind-speed derivative.',['눈 쪽으로 이동하면 등고선 값이 커진다.','인접선의 풍속 증가5kn을 방향거리 약10mi로 나눈다.'],['Wind speed increases toward the eye.','Divide the adjacent5kn increase by approximately10mi along that direction.'],'약 +0.5kn/mi.','Approximately +0.5kn/mi.','지도에서 국소 선간격을 판독한 근사로 위치에 따라 증가율은 달라진다.','A graphical local-spacing estimate; the rate changes with location.')
add(50,'z=2x²−y²와 z=4의 교선에서 (−2,2,4)의 접선을 구하라.','Find the tangent line to z=2x²−y²,z=4 at(−2,2,4).',['두 법선은 (4x,−2y,−1)=(−8,−4,−1), (0,0,1).','외적은 (−4,8,0)으로 (1,−2,0)에 평행하다.'],['Normals are (−8,−4,−1) and(0,0,1).','Their cross product(−4,8,0) is parallel to(1,−2,0).'],'x=−2+t,y=2−2t,z=4.','x=−2+t,y=2−2t,z=4.')
def extrema(n,F,pts=None,numeric=False,graph=False):
 fx=S.diff(F,x);fy=S.diff(F,y);H=S.hessian(F,(x,y));det=S.det(H)
 if pts is None:pts=[(a[x],a[y]) for a in S.solve([fx,fy],(x,y),dict=True)]
 ks=['정지식 '+M(fx)+'=0, '+M(fy)+'=0을 푼다.'];es=['Solve '+M(fx)+'=0 and '+M(fy)+'=0.'];ka=[];ea=[]
 for xx,yy in pts:
  sub={x:xx,y:yy};d=S.simplify(det.subs(sub));aa=S.simplify(H[0,0].subs(sub));val=S.simplify(F.subs(sub));assert abs(float(fx.subs(sub)))<1e-7 and abs(float(fy.subs(sub)))<1e-7
  kind=('안장점','saddle') if float(d)<0 else ('극소','minimum') if float(aa)>0 else ('극대','maximum');P=f'({float(xx):.3f},{float(yy):.3f})' if numeric else M(S.Tuple(xx,yy));V=f'{float(val):.3f}' if numeric else M(val)
  ks.append(P+'의 D='+M(d)+', fxx='+M(aa)+', '+kind[0]+'.');es.append(P+' has D='+M(d)+', fxx='+M(aa)+', hence '+kind[1]+'.');ka.append(P+' '+kind[0]+' '+V);ea.append(P+' '+kind[1]+' '+V)
 add(n,'f='+M(F)+'의 극값과 안장점을 구하라.'+(' 그래프도 그려 추정을 확인하라.' if graph else ''),'Find extrema and saddles of f='+M(F)+('. Plot to check estimates.' if graph else '.'),ks,es,'; '.join(ka),'; '.join(ea))
 if graph:plots[n]=(F,(-2,2,-2,2))
for row in [(51,x*x-x*y+y*y+9*x-6*y),(52,x**3-6*x*y+8*y**3),(53,3*x*y-x*x*y-x*y*y),(54,(x*x+y)*S.exp(y/2))]:extrema(*row)
add(55,'f=4xy²−x²y²−xy³를 꼭짓점(0,0),(0,6),(6,0)의 닫힌 삼각형에서 최적화하라.','Find absolute extrema of f=4xy²−x²y²−xy³ on the closed triangle with vertices(0,0),(0,6),(6,0).',['f=xy²(4−x−y). 양의 내부 정지점은 fx=y²(4−2x−y)=0, fy=xy(8−2x−3y)=0에서(1,2), 값4.','좌표축 경계의 값0. 빗변 x+y=6에서는 f=−2x(6−x)²로0≤x≤6, 정지점 x=2에서−64.'],['Write f=xy²(4−x−y). The positive interior stationary point is(1,2), value4, from fx=y²(4−2x−y)=0 and fy=xy(8−2x−3y)=0.','Axis boundaries give0. On x+y=6, f=−2x(6−x)² for0≤x≤6, minimized at x=2 with value−64.'],'최대4:(1,2). 최소−64:(2,4).','Maximum4 at(1,2); minimum−64 at(2,4).')
add(56,r'\(f=e^{-x^2-y^2}(x^2+2y^2)\)를 x²+y²≤4에서 최적화하라.',r'Find absolute extrema of \(f=e^{-x^2-y^2}(x^2+2y^2)\) on x²+y²≤4.',['내부 정지점은 (0,0),(±1,0),(0,±1), 값은0,1/e,2/e이다.','경계 r²=4에서 f=e^(−4)(4+y²), 값범위[4e^(−4),8e^(−4)]. 이 값들을 내부와 비교한다.'],['Interior stationary points are(0,0),(±1,0),(0,±1), with values0,1/e,2/e.','On r²=4, f=e^(−4)(4+y²), ranging from4e^(−4) to8e^(−4). Compare with the interior values.'],'최소0:(0,0). 최대2/e:(0,±1).','Minimum0 at(0,0); maximum2/e at(0,±1).')
