F=12+10*y-2*x*x-8*x*y-y**4;roots=[float(S.re(q)) for q in S.nroots(2*y**3-8*y-5) if abs(float(S.im(q)))<1e-9];pts=[(-2*b,b) for b in roots];extrema(58,F,pts,numeric=True,graph=True);plots[58]=(F,(-5,5,-3,3));highest=max([(float(F.subs({x:a,y:b})),a,b) for a,b in pts]);E[-1]['statement']['ko']+=' 소수 셋째 자리까지 계산하고 최고점을 구하라.';E[-1]['statement']['en']+=' Give three-decimal coordinates and find the highest point.';E[-1]['steps']['ko'].append('f=12+10y+8y²−y⁴−2(x+2y)²는 무한대에서−∞이므로 가장 큰 극대가 절대최대이다.');E[-1]['steps']['en'].append('Completing squares gives f=12+10y+8y²−y⁴−2(x+2y)², tending to−∞ at infinity, so the larger maximum is absolute.');E[-1]['answer']['ko']+=f'; 최고점({highest[1]:.3f},{highest[2]:.3f},{highest[0]:.3f}).';E[-1]['answer']['en']+=f'; highest point({highest[1]:.3f},{highest[2]:.3f},{highest[0]:.3f}).'
add(59,'f=x²y를 x²+y²=1에서 승수법으로 최적화하라.','Optimize f=x²y under x²+y²=1 by multipliers.',['2xy=2λx,x²=2λy. x=0이면 y=±1,값0.','x≠0이면 λ=y,x²=2y²이고 제약으로 y=±1/√3,x=±√(2/3).'],['Equations2xy=2λx,x²=2λy give x=0,y=±1, values0.','For x≠0, λ=y,x²=2y², so y=±1/√3,x=±√(2/3).'],r'최대 \(2/(3\sqrt3)\): y=1/√3. 최소 \(-2/(3\sqrt3)\): y=−1/√3. 둘 다 x=±√(2/3).',r'Maximum \(2/(3\sqrt3)\) for y=1/√3; minimum \(-2/(3\sqrt3)\) for y=−1/√3; both with x=±√(2/3).')
add(60,'f=1/x+1/y를 1/x²+1/y²=1에서 승수법으로 최적화하라.','Optimize f=1/x+1/y under1/x²+1/y²=1 by multipliers.',['−1/x²=λ(−2/x³),−1/y²=λ(−2/y³)에서 x=y=2λ.','제약으로 x=y=±√2. u=1/x,v=1/y로 바꾸면 단위원의 u+v이고 |u+v|≤√2이다.'],['Multiplier equations give x=y=2λ.','The constraint gives x=y=±√2. With u=1/x,v=1/y, the objective is u+v on a unit circle, bounded by±√2.'],'최대√2:(√2,√2), 최소−√2:(−√2,−√2).','Maximum√2 at(√2,√2); minimum−√2 at(−√2,−√2).')
add(61,'xyz를 x²+y²+z²=3에서 승수법으로 최적화하라.','Optimize xyz under x²+y²+z²=3 using multipliers.',['yz=2λx,xz=2λy,xy=2λz. 비영좌표에서는 x²=y²=z²=1이다.','좌표0인 후보는 목적값0. 세 부호의 곱에 따라±1이 나오며 |xyz|≤1이다.'],['Equations yz=2λx,xz=2λy,xy=2λz give x²=y²=z²=1 for nonzero coordinates.','Zero-coordinate candidates give0. Sign products give±1, and |xyz|≤1.'],'최대1: |x|=|y|=|z|=1, xyz>0. 최소−1: 같은 절댓값, xyz<0.','Maximum1 where all magnitudes are1 and xyz>0; minimum−1 where all magnitudes are1 and xyz<0.')
F=x*x+2*y*y+3*z*z;zz=t;yy=(t-1)/2;xx=(3-3*t)/2;g=S.expand(F.subs({x:xx,y:yy,z:zz},simultaneous=True));tc=S.solve(S.diff(g,t),t)[0];P=[S.simplify(a.subs(t,tc)) for a in [xx,yy,zz]];val=S.simplify(g.subs(t,tc))
add(62,'f=x²+2y²+3z²를 x+y+z=1,x−y+2z=2에서 승수법으로 최적화하라.','Optimize f=x²+2y²+3z² under x+y+z=1,x−y+2z=2 using multipliers.',['승수식은 (2x,4y,6z)=λ(1,1,1)+μ(1,−1,2)이며 제약과 함께 선형 연립계이다.','독립 확인으로 z=t,y=(t−1)/2,x=3(1−t)/2를 대입하면 f='+M(g)+'. 정지점 t='+M(tc)+'.'],['The multiplier system (2x,4y,6z)=λ(1,1,1)+μ(1,−1,2), together with constraints, is linear.','Independently substitute z=t,y=(t−1)/2,x=3(1−t)/2 to get f='+M(g)+', stationary at t='+M(tc)+'.'],'최소 '+M(val)+' at '+M(S.Tuple(*P))+'; 최대 없음.','Minimum '+M(val)+' at '+M(S.Tuple(*P))+'; no maximum.','축소 이차식의 최고차계수가 양수이므로 유일한 전역최소이며 위로 무한하다.','The reduced quadratic has positive leading coefficient, proving a unique global minimum and unboundedness above.')
# xy²z³=2 gives weighted squared-coordinate proportions1:2:3.
q=1/S.sqrt(3)
add(63,'xy²z³=2에서 원점에 가장 가까운 점들을 구하라.','Find points closest to the origin on xy²z³=2.',['거리제곱 x²+y²+z²의 승수식에 각각 x,y,z를 곱하면 2x²=2λ,2y²=4λ,2z²=6λ.','따라서 x²:y²:z²=1:2:3. x²=q라 놓으면 |xy²z³|=6√3 q³=2이므로 q³=1/(3√3), q=1/√3. x,z는 같은 부호여야 한다.'],['Multiplying squared-distance multiplier equations by x,y,z gives2x²=2λ,2y²=4λ,2z²=6λ.','Thus x²:y²:z²=1:2:3. Setting x²=q gives6√3 q³=2, hence q=1/√3; x,z must have matching signs.'],r'\(x=\pm3^{-1/4},y=\pm\sqrt2\,3^{-1/4},z=\pm3^{1/4}\), x,z 같은 부호; y 독립. 최단거리 \(\sqrt{2\sqrt3}\).',r'\(x=\pm3^{-1/4},y=\pm\sqrt2\,3^{-1/4},z=\pm3^{1/4}\), with matching x,z signs and independent y sign; shortest distance \(\sqrt{2\sqrt3}\).','가중 AM–GM으로 주어진 곱에서 제곱거리의 전역최소도 확인된다.','Weighted AM–GM also proves global minimality of the squared distance at the fixed product.')
add(64,'직선16x+15y=100 위의 점에서 (−3,0),(3,0)까지 거리합을 최소화한다. (a) 목적함수·등고선·최소점·값 (b) 그 점에서 기울기 평행을 확인하라.','Minimize the sum of distances to(−3,0),(3,0) over16x+15y=100. (a) Give the objective, contours, minimizing point and value; (b) verify parallel gradients.',[r'(a) \(f=\sqrt{(x+3)^2+y^2}+\sqrt{(x-3)^2+y^2}\). 등위곡선 f=c>6은 초점(±3,0)의 타원이다.',r'c=10이면 타원 \(x^2/25+y^2/16=1\). 직선은 (4,12/5)에서 이 타원에 접하고 거리들은37/5,13/5로 합10이다.',r'(b) 그 점의 \(\nabla f=(640,600)/481=(40/481)(16,15)=(40/481)\nabla g\).'],[r'(a) \(f=\sqrt{(x+3)^2+y^2}+\sqrt{(x-3)^2+y^2}\). Levels f=c>6 are ellipses with foci(±3,0).',r'For c=10, the ellipse is \(x^2/25+y^2/16=1\). The line is tangent at(4,12/5), whose distances are37/5 and13/5, summing to10.',r'(b) There \(\nabla f=(640,600)/481=(40/481)(16,15)=(40/481)\nabla g\).'],'최소10, (a,b)=(4,12/5).','Minimum10 at(a,b)=(4,12/5).','거리합은 볼록함수이므로 제약선에서 정지한 점은 전역최소이다.','A sum of distances is convex, so its stationary point on the constraint line is a global minimum.',['a','b'])
add(65,'직사각형 위에 이등변삼각형 지붕을 얹은 오각형의 둘레가 P이다. 넓이를 최대화하는 다섯 변의 길이를 구하라.','A pentagon consists of a rectangle topped by an isosceles triangle and has perimeter P. Find the five side lengths maximizing area.',['밑변 b,직사각 높이 h,지붕 상승 a,빗변 l=√(a²+b²/4). 넓이 bh+ba/2, 둘레 b+2h+2l=P.','승수식의 h성분에서 λ=b/2, a성분에서 a=l/2. 따라서 지붕각30°, b=√3l이다.','b성분은 h+a/2=λ(1+b/(2l)), 따라서 h=(1+√3)l/2. 둘레식으로 l=P/(3+2√3).'],['Let base b, rectangle height h, roof rise a and slope l=√(a²+b²/4). Area is bh+ba/2 and perimeter b+2h+2l=P.','The h multiplier equation gives λ=b/2; the a equation gives a=l/2, hence roof angle30° and b=√3l.','The b equation gives h+a/2=λ(1+b/(2l)), yielding h=(1+√3)l/2 and l=P/(3+2√3).'],r'\(l=P/(3+2\sqrt3)\). 지붕 두 변 l,l; 수직 두 변 \((1+\sqrt3)l/2\); 밑변 \(\sqrt3l\).',r'Let \(l=P/(3+2\sqrt3)\). Roof sides l,l; vertical sides \((1+\sqrt3)l/2\); base \(\sqrt3l\).','각 θ에서 빗변 최적화 후 면적은 P²cosθ/[4(2+2cosθ−sinθ)]. 그 미분 부호는1−2sinθ이므로30°에서 유일한 최대이다.','After optimizing slope length at fixedθ, area is P²cosθ/[4(2+2cosθ−sinθ)]. Its derivative has sign1−2sinθ, giving the unique maximum at30°.')
E.sort(key=lambda a:a['number']);assert [a['number'] for a in E]==list(range(1,66))
D=dict(section='14.9',source=dict(title='Calculus',edition='9',language='en',printedPages=[1070,1071,1072],pdfPages=[1107,1108,1109]),scope=dict(kind='review',numbers=list(range(1,66)),total=65,note=pair('Chapter14 Review Exercises 전체65문항과 모든 소문항.','All65 Chapter14 Review Exercises and every subpart.')),exercises=E)
(R/'exercise-content/s14-9.json').write_text(json.dumps(D,ensure_ascii=False,indent=2)+'\n');print('Chapter14 Review:65 cards')
